content:
{
 "kind": "sequence",
 "format": 1,
 "id": "seq_deadball_open",
 "name": "Deadball: pregame",
 "set": "set_ksab5_desk",
 "roles": {
  "a": {
   "mark": "a",
   "label": "Lead anchor"
  },
  "b": {
   "mark": "b",
   "label": "Analyst"
  }
 },
 "wallText": "{away} at {home}",
 "wallSub": "KSAB5 Sports",
 "beats": [
  {
   "id": "b1",
   "shot": {
    "cam": "jib",
    "frame": "full",
    "on": [
     "a",
     "b"
    ],
    "move": "crane",
    "cut": "dissolve"
   },
   "gfx": [],
   "hold": 3.2,
   "wall": "brand"
  },
  {
   "id": "b2",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "a"
    ],
    "move": "drift",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "Welcome in. I'm {a.name}, this is {b.name}, and tonight it's {away} at {home}.",
     "Thanks for joining us. {away} and {home} tonight, live from {venue}."
    ]
   },
   "gfx": [
    {
     "kind": "lower",
     "text": "{a.name}",
     "sub": "KSAB5 Sports",
     "at": 0.4,
     "for": 5
    }
   ]
  },
  {
   "id": "b3",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "b"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "b",
    "lines": [
     "{away} are {awayRecord}. {home} are {homeRecord}. It's a long season, but these two know each other.",
     "{home} come in at {homeRecord}. {away} are {awayRecord}, and they haven't been hitting."
    ]
   },
   "gfx": [
    {
     "kind": "table",
     "title": "Tonight",
     "rows": [
      "{away}: {awayRecord}",
      "{home}: {homeRecord}"
     ],
     "side": "right",
     "at": 0.3,
     "for": 0
    },
    {
     "kind": "lower",
     "text": "{b.name}",
     "sub": "Analyst",
     "at": 0.4,
     "for": 5
    }
   ],
   "wall": "list",
   "wallList": "table",
   "wallRow": "{n}. {team}: {wins}-{losses}",
   "wallText": "Standings"
  },
  {
   "id": "b4",
   "shot": {
    "cam": "cam2",
    "frame": "medium",
    "on": [
     "a"
    ],
    "move": "drift",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "There's news on the injury front. {missingSaid} out tonight.",
     "{away} and {home} aren't at full strength. That's {missingSaid} missing between them."
    ]
   },
   "gfx": [
    {
     "kind": "table",
     "title": "Out tonight",
     "list": "missing",
     "row": "{name}",
     "limit": 6,
     "side": "right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "missingCount",
     "op": ">",
     "value": 0
    }
   ]
  },
  {
   "id": "b5",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "a"
    ],
    "move": "drift",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "Who's the bat to watch tonight, {b.name}?",
     "One name for you tonight. {star.name}, {star.said}."
    ]
   },
   "gfx": [
    {
     "kind": "profile",
     "who": "star",
     "side": "right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "star",
     "op": "has"
    }
   ]
  },
  {
   "id": "b6",
   "shot": {
    "cam": "cam3",
    "frame": "close",
    "on": [
     "b"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "b",
    "lines": [
     "{star.name} has been seeing the ball. Pitch around him if you can.",
     "Keep {star.name} off the bases and you're halfway there."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "star",
     "op": "has"
    }
   ]
  },
  {
   "id": "b7",
   "shot": {
    "cam": "cam1",
    "frame": "two",
    "on": [
     "a",
     "b"
    ],
    "move": "pull",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "{announcer} has the call from {venue}. First pitch is coming up.",
     "Let's go down to {announcer} at {venue}."
    ]
   },
   "gfx": [
    {
     "kind": "pip",
     "source": "feed",
     "title": "Live: {venue}",
     "corner": "top-right",
     "at": 0,
     "for": 0
    }
   ],
   "wall": "feed"
  }
 ]
}
